const notes = {
  meeting:{title:'产品周会 · 10月12日', category:'会议记录', path:'项目 / 素记 Plainote', html:`<h1>产品周会 · 10月12日</h1><p class="participants">参与：产品、设计、研发 &nbsp; · &nbsp; 10:00 — 10:45</p><p>这一周，我们先把素记的日常使用体验做清楚：打开笔记，开始记录，再轻松找到需要的信息。</p><h2 id="goal">会议目标</h2><p>确认第一版的界面方向，让工作笔记有一个安静、清晰的落脚点。</p><p class="summary">以写作为中心。保留熟悉的文件夹和标签页，让搜索、链接与大纲在需要时自然出现。</p><h2 id="discussion">讨论事项</h2><ul><li><strong>编辑体验：</strong>默认即时预览，同时保留源码模式。</li><li><strong>资料整理：</strong>直接打开已有笔记库，沿用原来的目录。</li><li><strong>界面层级：</strong>暖白与墨色为主，青绿色只标记重要状态。</li></ul><h2 id="tasks">下一步</h2><ul class="task-list" contenteditable="false"><li><input id="task-1" type="checkbox" checked><label for="task-1">确定主窗口的文稿居中布局</label></li><li><input id="task-2" type="checkbox"><label for="task-2">查看浅色与深色主题的界面原型</label></li><li><input id="task-3" type="checkbox"><label for="task-3">评审搜索、模板与保存异常的交互</label></li></ul><h2 id="related">相关笔记</h2><p><a href="#overview" data-link="overview">项目概览</a> &nbsp; <a href="#design" data-link="design">界面设计原则</a></p>`},
  overview:{title:'素记 · 项目概览',category:'项目文档',path:'项目 / 素记 Plainote',html:`<h1>素记 · 项目概览</h1><p class="participants">Plainote &nbsp; · &nbsp; 本地 Markdown 工作笔记</p><p>把会议记录、项目资料和工作日志放在熟悉的文件夹里，让每次打开都能接着写。</p><h2 id="position">产品方向</h2><p>支持 macOS 与 Windows，第一版专注单机使用。已有的 Markdown 文件、双向链接和图片可以继续使用。</p><h2 id="scope">第一版范围</h2><table><thead><tr><th>能力</th><th>使用场景</th></tr></thead><tbody><tr><td>即时预览</td><td>专注记录会议与工作内容</td></tr><tr><td>搜索与快速打开</td><td>找回项目资料和历史笔记</td></tr><tr><td>模板</td><td>快速开始一份会议记录</td></tr><tr><td>双向链接</td><td>连接相关项目与讨论</td></tr></tbody></table><h2 id="progress">当前进展</h2><p>已确定文稿居中的界面布局。正在评审界面原型，后续再实现实际的编辑器和文件管理。</p><h2 id="related">相关记录</h2><p>本周的设计结论见 <a href="#meeting" data-link="meeting">产品周会 · 10月12日</a>。</p>`},
  design:{title:'界面设计原则',category:'项目文档',path:'项目 / 素记 Plainote',html:`<h1>界面设计原则</h1><p class="participants">温润素雅 &nbsp; · &nbsp; 工作优先</p><p>让工具安静地服务写作，让重要的信息始终清晰。</p><h2 id="hierarchy">清晰的层级</h2><ul><li>正文优先，目录与辅助信息保持适度密度。</li><li>使用底色和细分隔线区分区域。</li><li>青绿色表示当前选择、链接和键盘焦点。</li></ul><h2 id="readability">长时间阅读</h2><p>正文保持舒适的行宽和行距，尊重中文字体与系统缩放。浅色与深色主题各自验证可读性。</p><h2 id="reliability">可理解的反馈</h2><p>保存状态明确显示。失败时保留编辑内容，提供重试和另存为；文件冲突让用户看见两个版本。</p><h2 id="related">相关笔记</h2><p><a href="#meeting" data-link="meeting">产品周会 · 10月12日</a> &nbsp; <a href="#overview" data-link="overview">项目概览</a></p>`},
  log:{title:'本周工作日志',category:'工作日志',path:'工作日志',html:`<h1>本周工作日志</h1><p class="participants">2026年10月12日 — 10月16日</p><h2 id="monday">周一 · 10月12日</h2><p>完成产品周会，明确素记的界面方向。</p><ul><li>确认默认即时预览与本地文件管理。</li><li>确认暖白、墨色与少量青绿色的视觉气质。</li><li>开始查看主窗口、搜索与异常状态。</li></ul><h2 id="focus">本周重点</h2><ul class="task-list" contenteditable="false"><li><input id="log-task-1" type="checkbox"><label for="log-task-1">评审素记的界面原型</label></li><li><input id="log-task-2" type="checkbox"><label for="log-task-2">整理编辑器验证任务</label></li></ul><h2 id="related">相关记录</h2><p><a href="#meeting" data-link="meeting">产品周会 · 10月12日</a></p>`}
};
let active='meeting', openNotes=['overview','meeting','log'], isSource=false, searchVisible=false, saveTimer, toastTimer, quickSelected=0, quickMatches=[], currentSave='saved';
let conflictSnapshot=null;
const app=$('#app'), dialog=$('#dialog');
function plainText(html){const d=document.createElement('div');d.innerHTML=html;return d.textContent;}
function markdownFor(html){const d=document.createElement('div');d.innerHTML=html;return [...d.children].map(el=>{
  if(/^H[1-6]$/.test(el.tagName))return '#'.repeat(Number(el.tagName[1]))+' '+el.textContent;
  if(el.tagName==='UL')return [...el.children].map(li=>li.querySelector('input')?'- ['+(li.querySelector('input').checked?'x':' ')+'] '+li.textContent:'- '+li.textContent).join('\n');
  if(el.tagName==='TABLE')return [...el.rows].map(row=>'| '+[...row.cells].map(c=>c.textContent).join(' | ')+' |').join('\n');
  let result=el.innerHTML.replace(/<a[^>]*data-link="([^"]+)"[^>]*>(.*?)<\/a>/g,(_,id,text)=>`[[${notes[id]?.title||id}|${text}]]`).replace(/<strong>(.*?)<\/strong>/g,'**$1**');
  return plainText(result);
}).join('\n\n');}
function inlineMarkdown(text){return escapeHTML(text).replace(/\[\[([^|\]]+)(?:\|([^\]]+))?\]\]/g,(_,title,label)=>{const id=Object.keys(notes).find(id=>notes[id].title===title);return id?`<a href="#${id}" data-link="${id}">${label||title}</a>`:label||title;}).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');}
function renderMarkdown(text){return text.split('\n').map((line,i)=>{const heading=line.match(/^(#{1,6})\s+(.+)/);if(heading)return `<h${heading[1].length} id="source-${i}">${inlineMarkdown(heading[2])}</h${heading[1].length}>`;if(line.startsWith('- '))return `<p>• ${inlineMarkdown(line.slice(2))}</p>`;return line.trim()?`<p>${inlineMarkdown(line)}</p>`:'';}).join('');}
function persistCurrent(){if(isSource){notes[active].markdown=$('#source-editor').value;notes[active].html=renderMarkdown(notes[active].markdown);}else notes[active].html=$('#document').innerHTML;}
function renderTabs(){const tabs=$('#tabs');tabs.innerHTML=openNotes.map(id=>`<div class="tab ${id===active?'active':''}"><button class="tab-select" role="tab" aria-selected="${id===active}" data-open="${id}">${svg('file')}<span class="tab-label">${escapeHTML(notes[id].title)}</span></button><button class="tab-close" data-close="${id}" aria-label="关闭 ${escapeHTML(notes[id].title)}">${svg('close')}</button></div>`).join('')+`<button class="tab-add" aria-label="新建笔记">${svg('plus')}</button>`;}
function updateCount(){const text=isSource?$('#source-editor').value:$('#document').innerText;$('#word-count').textContent=`${text.replace(/\s/g,'').length} 字`;}
function updateOutline(){const headings=[...$('#document').querySelectorAll('h1,h2,h3')];$('#outline').innerHTML=headings.length?headings.map((h,i)=>`<button class="${i===0?'current':''}" data-heading="${i}">${escapeHTML(h.textContent)}</button>`).join(''):'<p class="empty-outline">添加标题后，可以在这里浏览笔记结构。</p>';}
function updateBacklinks(){const linked=Object.keys(notes).filter(id=>id!==active&&notes[id].html.includes(`data-link="${active}"`));$('#backlinks-tab').innerHTML=`反向链接 <span>${linked.length}</span>`;$('#backlinks').innerHTML='<p class="inspector-caption">这些笔记引用了当前笔记</p>'+(linked.length?linked.map(id=>`<button class="backlink" data-note="${id}">${svg('file')}<strong>${escapeHTML(notes[id].title)}</strong><small>${escapeHTML(notes[id].path)}</small></button>`).join(''):'<p class="empty-outline">还没有笔记引用这里。<br>在其他笔记中使用 [[笔记名称]] 建立关联。</p>');}
function openNote(id){if(!notes[id])return;persistCurrent();active=id;if(!openNotes.includes(id))openNotes.push(id);$('#document').innerHTML=notes[id].html;$('#source-editor').value=notes[id].markdown||markdownFor(notes[id].html);$('#note-category').textContent=notes[id].category;$('#breadcrumb-name').textContent=notes[id].title;$('#document-scroll').scrollTop=0;renderTabs();document.querySelectorAll('[data-note]').forEach(el=>{const selected=el.dataset.note===id;el.classList.toggle('selected',selected);if(selected)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});updateOutline();updateBacklinks();updateCount();closeWelcome();}
function showToast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function setSave(state){currentSave=state;const el=$('#save-status');el.style.color=state==='failed'?'var(--error)':'';el.innerHTML=svg(state==='failed'?'warning':state==='saving'?'more':'check')+(state==='failed'?'保存失败 · 演示':state==='saving'?'正在保存 · 演示':'已保存 · 演示');}
function queueSave(){updateCount();setSave('saving');clearTimeout(saveTimer);saveTimer=setTimeout(()=>{persistCurrent();setSave($('#notice').classList.contains('error')&&!$('#notice').hidden?'failed':'saved');},700);}
function setTheme(theme){document.documentElement.dataset.theme=theme;$('#theme-toggle').innerHTML=svg(theme==='dark'?'sun':'moon')+`<span>${theme==='dark'?'浅色模式':'深色模式'}</span>`;}
function closeDialog(){dialog.close();}
function openDialog(title,body){$('#dialog-content').innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-dialog-close aria-label="关闭">${svg('close')}</button></div><div class="dialog-body">${body}</div>`;dialog.showModal();}
function openQuick(){quickSelected=0;$('#dialog-content').innerHTML=`<h2 id="dialog-title" class="sr-only">快速打开笔记</h2><input class="quick-input" id="quick-input" aria-label="快速打开笔记" placeholder="输入笔记名称…" autocomplete="off"><div class="quick-results" id="quick-results"></div><div class="dialog-footnote"><span>↑ ↓ 选择</span><span>回车 打开</span><span>Esc 关闭</span></div>`;dialog.showModal();renderQuick('');$('#quick-input').focus();}
function renderQuick(query){quickMatches=Object.keys(notes).filter(id=>notes[id].title.toLowerCase().includes(query.toLowerCase()));quickSelected=Math.max(0,Math.min(quickSelected,quickMatches.length-1));$('#quick-results').innerHTML=quickMatches.length?quickMatches.map((id,i)=>`<button class="quick-row ${i===quickSelected?'current':''}" data-quick="${id}">${svg('file')}<span>${escapeHTML(notes[id].title)}<small>${notes[id].path}</small></span></button>`).join(''):'<p class="empty-search">没有找到笔记，试试其他名称。</p>';}
function toggleSearch(force){searchVisible=force??!searchVisible;$('#files-pane').hidden=searchVisible;$('#search-pane').hidden=!searchVisible;app.classList.remove('hide-left');if(innerWidth<=700)app.classList.add('show-left');if(searchVisible){$('#full-search').focus();renderSearch($('#full-search').value);}}
function renderSearch(query){persistCurrent();const matches=Object.keys(notes).filter(id=>(notes[id].title+plainText(notes[id].html)).toLowerCase().includes(query.toLowerCase()));$('#search-count').textContent=query?`${matches.length} 篇笔记包含“${query}”`:'输入文字，搜索示例笔记库';$('#search-results').innerHTML=query?(matches.length?matches.map(id=>{const text=plainText(notes[id].html);const index=text.indexOf(query);const snippet=text.slice(Math.max(0,index-18),Math.max(0,index-18)+90);return `<button class="search-result" data-result="${id}"><strong>${escapeHTML(notes[id].title)}</strong><small class="result-path">${notes[id].path}</small><small>${escapeHTML(snippet)}…</small></button>`;}).join(''):'<div class="empty-search">没有找到匹配内容。<br>试试“界面”“工作”或“会议”。</div>'):'';}
function openTemplates(){openDialog('新建笔记',`<p class="dialog-copy">选择一个起点，笔记将创建在当前项目中。</p>${[['blank','空白笔记','从一个想法开始'],['meeting','会议记录','会议目标、讨论事项与下一步'],['project','项目文档','背景、目标与项目进展'],['log','工作日志','今日记录与待办事项']].map(([id,title,description])=>`<button class="template-option" data-template="${id}"><span>${svg(id==='log'?'calendar':'file')}</span><div><strong>${title}</strong><small>${description}</small></div></button>`).join('')}<p class="dialog-copy" style="margin-top:18px;margin-bottom:0">原型中新建的内容仅保留在当前页面。</p>`);}
function createNote(template){persistCurrent();const titles={blank:'未命名笔记',meeting:'新会议记录',project:'新项目文档',log:'新工作日志'};const id='new-'+Date.now();let title=titles[template];let number=2;while(Object.values(notes).some(note=>note.title===title))title=titles[template]+' '+number++;const sections={blank:[],meeting:['会议目标','讨论事项','下一步'],project:['项目背景','目标','当前进展'],log:['今日记录','待办事项']}[template];notes[id]={title,category:template==='meeting'?'会议记录':template==='log'?'工作日志':'项目文档',path:'项目 / 素记 Plainote',html:`<h1>${title}</h1>${sections.map((s,i)=>`<h2 id="new-${i}">${s}</h2><p>在这里开始记录…</p>`).join('')||'<p>在这里开始记录…</p>'}`};$('#created-files').insertAdjacentHTML('beforeend',`<button class="file-row" data-note="${id}">${svg('file')}<span>${title}</span></button>`);closeDialog();openNote(id);$('#document').focus();showToast('已创建示例笔记，内容仅保留在当前页面。');}
function openSettings(){const theme=document.documentElement.dataset.theme||'light';openDialog('设置',`<p class="dialog-copy">调整适合自己的阅读与工作环境。</p><div class="setting-row"><div><strong>外观</strong><small>明暗主题使用相同的界面结构。</small></div><div class="segmented"><button data-theme-choice="light" aria-pressed="${theme==='light'}">浅色</button><button data-theme-choice="dark" aria-pressed="${theme==='dark'}">深色</button></div></div><div class="setting-row"><div><strong>正文字号</strong><small><span id="font-size-label">${parseInt(getComputedStyle($('#document')).fontSize)} px</span></small></div><input type="range" id="font-size" min="14" max="20" value="${parseInt(getComputedStyle($('#document')).fontSize)}" aria-label="正文字号"></div><div class="setting-row"><div><strong>窗口平台预览</strong><small>查看不同系统的窗口控件布局。</small></div><div class="segmented"><button data-platform="mac" aria-pressed="${!app.classList.contains('windows')}">macOS</button><button data-platform="windows" aria-pressed="${app.classList.contains('windows')}">Windows</button></div></div><div class="setting-row"><div><strong>附件位置</strong><small>沿用笔记库中的附件目录。</small></div><span class="setting-value">附件 /</span></div><p class="dialog-copy" style="margin-top:20px;margin-bottom:0">设置仅作用于当前原型页面，不会修改本地笔记。</p>`);}
function toggleSource(){persistCurrent();isSource=!isSource;$('#document').hidden=isSource;$('#source-editor').hidden=!isSource;$('#source-toggle').setAttribute('aria-pressed',String(isSource));$('#source-editor').value=notes[active].markdown||markdownFor(notes[active].html);if(!isSource){$('#document').innerHTML=notes[active].html;updateOutline();}$('#preview-mode').textContent=isSource?'源码模式':'即时预览';updateCount();}
function closeWelcome(){app.classList.remove('welcome-mode');$('#welcome').hidden=true;}
function showWelcome(){dialog.open&&closeDialog();app.classList.add('welcome-mode');$('#welcome').hidden=false;}
function showFailure(){closeDialog();$('#notice').hidden=false;$('#notice').className='notice error';$('#notice').innerHTML=`<span>${svg('warning')}</span><p><strong>无法保存这篇笔记。</strong> 内容仍保留在编辑区，请重试或另存为。<br><small>演示原因：目标文件夹没有写入权限。</small></p><button data-retry>重试保存</button><button data-save-copy>另存为示例副本</button>`;setSave('failed');}
function showConflict(){persistCurrent();const currentHtml=notes[active].html;const diskChange='先验证即时预览和文件保存，再评审其他交互';const originalLine='评审搜索、模板与保存异常的交互';const diskHtml=currentHtml.includes(originalLine)?currentHtml.replace(originalLine,diskChange):currentHtml+`<h2>外部修改（示例）</h2><p>${diskChange}。</p>`;conflictSnapshot={noteId:active,currentHtml,diskHtml};const currentExcerpt=currentHtml.includes(originalLine)?'下一步：'+originalLine+'。':plainText(currentHtml).slice(0,120);openDialog('这篇笔记有两个版本',`<p class="dialog-copy">文件被其他应用修改，你的编辑也尚未保存。先查看差异，再选择保留方式。以下均为演示内容。</p><div class="conflict-versions"><div><strong>当前编辑内容</strong><p>${escapeHTML(currentExcerpt)}</p></div><div><strong>磁盘上的内容</strong><p>下一步：${diskChange}。</p></div></div><div class="dialog-buttons"><button class="secondary-button" data-dialog-close>稍后处理</button><button class="primary-button" data-keep-both>保留两个版本</button></div>`);}
function demoStates(){openDialog('查看界面状态',`<p class="dialog-copy">这些入口用于评审产品在不同状态下的表现。</p><div class="state-options"><button data-state="welcome">首次打开<span>还没有选择笔记库时的入口。</span></button><button data-state="failure">保存失败<span>内容保留、错误说明与恢复操作。</span></button><button data-state="conflict">外部修改冲突<span>比较两个版本，并保留副本。</span></button><button data-state="normal">返回正常状态<span>关闭异常提示，继续查看笔记。</span></button></div>`);}
document.addEventListener('click',event=>{
  const target=event.target.closest('button,a,[data-link]');if(!target)return;
  if(target.dataset.note)openNote(target.dataset.note);
  if(target.dataset.open)openNote(target.dataset.open);
  if(target.dataset.close){event.stopPropagation();const id=target.dataset.close;if(openNotes.length===1){showToast('至少保留一个笔记标签。');return;}persistCurrent();openNotes=openNotes.filter(n=>n!==id);if(active===id)openNote(openNotes[0]);else renderTabs();}
  if(target.classList.contains('tab-add'))openTemplates();
  if(target.dataset.link){event.preventDefault();openNote(target.dataset.link);}
  if(target.dataset.heading){$('#document').querySelectorAll('h1,h2,h3')[Number(target.dataset.heading)]?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});$('#outline').querySelectorAll('button').forEach(b=>b.classList.toggle('current',b===target));}
  if(target.dataset.quick){closeDialog();openNote(target.dataset.quick);}
  if(target.dataset.result)openNote(target.dataset.result);
  if(target.hasAttribute('data-dialog-close'))closeDialog();
  if(target.dataset.template)createNote(target.dataset.template);
  if(target.dataset.themeChoice){setTheme(target.dataset.themeChoice);dialog.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));}
  if(target.dataset.platform){app.classList.toggle('windows',target.dataset.platform==='windows');dialog.querySelectorAll('[data-platform]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));}
  if(target.dataset.state){const state=target.dataset.state;if(state==='welcome')showWelcome();if(state==='failure')showFailure();if(state==='conflict')showConflict();if(state==='normal'){closeDialog();$('#notice').hidden=true;closeWelcome();setSave('saved');}}
  if(target.hasAttribute('data-retry')){$('#notice').hidden=true;setSave('saved');showToast('演示：保存成功，编辑内容已保留。');}
  if(target.hasAttribute('data-save-copy')||target.hasAttribute('data-keep-both')){persistCurrent();const keepBoth=target.hasAttribute('data-keep-both');const original=notes[keepBoth?conflictSnapshot.noteId:active];const id='copy-'+Date.now();const title=original.title+(keepBoth?' · 外部版本':' · 副本');const html=(keepBoth?conflictSnapshot.diskHtml:original.html).replace(/<h1[^>]*>.*?<\/h1>/,`<h1>${escapeHTML(title)}</h1>`);notes[id]={...original,title,html,markdown:null};$('#created-files').insertAdjacentHTML('beforeend',`<button class="file-row" data-note="${id}">${svg('file')}<span>${escapeHTML(title)}</span></button>`);dialog.open&&closeDialog();$('#notice').hidden=true;openNote(id);setSave('saved');showToast(keepBoth?'已保留当前内容和外部版本，两份示例都在当前页面。':'已保留当前内容的示例副本。');}
  if(target.dataset.menu==='quick'){closeDialog();openQuick();}
  if(target.dataset.menu==='templates'){closeDialog();openTemplates();}
  if(target.dataset.menu==='copy'){navigator.clipboard?.writeText(notes[active].markdown||markdownFor(notes[active].html)).then(()=>showToast('已复制示例 Markdown。')).catch(()=>showToast('浏览器未允许复制，请切换源码模式手动复制。'));closeDialog();}
});
$('#tabs').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;const index=openNotes.indexOf(active),next=(index+(event.key==='ArrowRight'?1:-1)+openNotes.length)%openNotes.length;event.preventDefault();openNote(openNotes[next]);$('#tabs').querySelector('[aria-selected="true"]').focus();});
