dialog.addEventListener('click',event=>{const r=dialog.getBoundingClientRect();if(event.target===dialog&&(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom))closeDialog();});
document.addEventListener('input',event=>{if(event.target.id==='quick-input'){quickSelected=0;renderQuick(event.target.value);}if(event.target.id==='font-size'){$('#document').style.fontSize=event.target.value+'px';$('#font-size-label').textContent=event.target.value+' px';}});
document.addEventListener('keydown',event=>{const mod=event.metaKey||event.ctrlKey;if(dialog.open){if($('#quick-input')&&['ArrowDown','ArrowUp','Enter'].includes(event.key)){event.preventDefault();if(event.key==='Enter'&&quickMatches[quickSelected]){closeDialog();openNote(quickMatches[quickSelected]);}else{quickSelected+=event.key==='ArrowDown'?1:-1;renderQuick($('#quick-input').value);}}return;}if(mod&&event.key.toLowerCase()==='p'){event.preventDefault();openQuick();}if(mod&&event.shiftKey&&event.key.toLowerCase()==='f'){event.preventDefault();toggleSearch(true);}if(mod&&event.key.toLowerCase()==='n'){event.preventDefault();openTemplates();}if(mod&&event.key===','){event.preventDefault();openSettings();}});
